from pathlib import Path
import bpy,numpy as np,json,hashlib
R=Path(__file__).resolve().parent;bpy.ops.wm.open_mainfile(filepath=str(R/'scene.blend'));d=np.load(R/'mesh.npz');obs=[o for o in bpy.data.objects if o.type=='MESH' and 'source_mesh_sha256' in o];assert len(obs)==1;o=obs[0];assert o['source_mesh_sha256']==hashlib.sha256((R/'mesh.npz').read_bytes()).hexdigest();v=np.array([x.co[:] for x in o.data.vertices]);f=np.array([p.vertices[:] for p in o.data.polygons]);m=np.array([p.material_index for p in o.data.polygons]);assert np.allclose(v,d['vertices'],atol=.00003);assert np.array_equal(f,d['faces']);assert np.array_equal(m,d['materials']);r={'status':'PASS','opened_actual_blend':True,'mesh_identity':o['source_mesh_sha256'],'faces':len(f),'materials_match':True};(R/'SCENE-QA.json').write_text(json.dumps(r,indent=2));print(r)
